public static int removeDuplicates(int[] arr) {
    if (arr.length == 0) return 0;
    Arrays.sort(arr); // Group duplicates together

    int j = 0; // Pointer for unique elements
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != arr[j]) {
            j++;
            arr[j] = arr[i]; // Move the unique element to the front
        }
    }
    return j + 1; // Return the count of unique elements
}

public static char findFirstRepeating(String str) {
    HashSet<Character> seen = new HashSet<>();
    for (char c : str.toCharArray()) {
        if (!seen.add(c)) {
            return c; // add() returns false if it already exists
        }
    }
    return '\0';
}

public static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;

    // Check odd factors up to the square root of n
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

